43	/**
44	 * Reads the durable generation/seq high-water floors for `nodeId` directly
45	 * from the real IndexedDB store `rotation-state.service.ts` writes to.
46	 * Read-only observation -- does not invoke any app resolve/enforce logic.
47	 */
48	async function readDurableFloors(
49	  page: Page,
50	  nodeId: string
51	): Promise<{ generation: number | undefined; seq: number | undefined }> {
52	  return page.evaluate(
53	    ({ nodeId }) => {
54	      return new Promise<{ generation: number | undefined; seq: number | undefined }>(
55	        (resolve, reject) => {
56	          // No version argument: open at whatever version the service created
57	          // so this read-only probe never races a future DB_VERSION bump.
58	          const req = indexedDB.open('cipherbox-rotation-state');
59	          req.onerror = () => reject(req.error);
60	          req.onsuccess = () => {
61	            const db = req.result;
62	            // The DB (or its stores) may not exist yet — e.g. a fresh profile
63	            // where rotation-state.service.ts has never written. Treat that as
64	            // "no floors recorded" instead of throwing synchronously.
65	            if (
66	              !db.objectStoreNames.contains('generation-high-water') ||
67	              !db.objectStoreNames.contains('seq-high-water')
68	            ) {
69	              resolve({ generation: undefined, seq: undefined });
70	              return;
71	            }
72	            try {
73	              const tx = db.transaction(['generation-high-water', 'seq-high-water'], 'readonly');
74	              const genReq = tx.objectStore('generation-high-water').get(nodeId);
75	              const seqReq = tx.objectStore('seq-high-water').get(nodeId);
76	              tx.oncomplete = () => {
77	                resolve({
