102	 * `rotation-state.service.ts` -- so `put(value, key)` passes the value first
103	 * and the nodeId key second.
104	 */
105	async function writeDurableSeqFloor(page: Page, nodeId: string, value: number): Promise<void> {
106	  await page.evaluate(
107	    ({ nodeId, value }) => {
108	      return new Promise<void>((resolve, reject) => {
109	        // No version argument: open at whatever version the service created so
