111	        const req = indexedDB.open('cipherbox-rotation-state');
112	        req.onerror = () => reject(req.error);
113	        req.onsuccess = () => {
114	          const db = req.result;
115	          if (!db.objectStoreNames.contains('seq-high-water')) {
116	            reject(new Error('seq-high-water store missing -- durable floor not yet seeded'));
117	            return;
118	          }
119	          try {
120	            const tx = db.transaction('seq-high-water', 'readwrite');
121	            tx.objectStore('seq-high-water').put(value, nodeId);
